DECLARE @a NUMERIC(20,2) = (SELECT SUM(금액) FROM [DOI_ETC_INOUT] WHERE [yyyymm]='202608');
IF @after <> 158 BEGIN SET @ok=0; SET @msg=@msg+N'행수 158 기대, 실제 '+CAST(@after AS NVARCHAR(20))+N'; '; END
IF ABS(@q - 94163) > 0.5 BEGIN SET @ok=0; SET @msg=@msg+N'수량 합계 불일치(기대 94,163, 실제 '+CAST(@q AS NVARCHAR(30))+N'); '; END
IF ABS(@a - 2122500147) > 0.5 BEGIN SET @ok=0; SET @msg=@msg+N'금액 합계 불일치(기대 2,122,500,147, 실제 '+CAST(@a AS NVARCHAR(30))+N'); '; END

IF @ok = 1
BEGIN
  COMMIT;
  SELECT N'DOI_ETC_INOUT 적재 완료' AS 결과, @before AS 삭제전, @after AS 적재행수, @q AS 수량합, @a AS 금액합;
  SELECT 입출고구분, COUNT(*) AS 행수, SUM(수량) AS 수량, SUM(금액) AS 금액
    FROM DOI_ETC_INOUT WHERE yyyymm='202608' GROUP BY 입출고구분;
END
ELSE
BEGIN
  ROLLBACK;
  SELECT N'DOI_ETC_INOUT 검증 실패 — 원상복구' AS 결과, @msg AS 사유;
END
GO